frappe.ui.form.on('Sales Invoice', {

    setup: function(frm) {
        // Filter Sales Taxes and Charges Template by Company
        frm.set_query('taxes_and_charges', function() {
            return {
                filters: {
                    company: frm.doc.company
                }
            };
        });
    },

    cost_center: function(frm) {

        // Clear template if Cost Center is removed
        if (!frm.doc.cost_center) {
            frm.set_value('taxes_and_charges', '');
            return;
        }

        // Fetch Sales Taxes and Charges Template from Cost Center
        frappe.db.get_value(
            'Cost Center',
            frm.doc.cost_center,
            'custom_sales_taxes_and_charges'
        ).then(r => {

            const template = r.message?.custom_sales_taxes_and_charges;

            if (template) {
                frm.set_value('taxes_and_charges', template);
            } else {
                frm.set_value('taxes_and_charges', '');

                frappe.show_alert({
                    message: __('No Sales Taxes and Charges Template is configured for this Cost Center'),
                    indicator: 'orange'
                });
            }
        });
    }
});

