    },

    is_return(frm) {
        set_naming_series(frm);
    }
});

function set_naming_series(frm) {
    let company = frm.doc.company;
    let is_return = frm.doc.is_return;

    if (company === "Doodle Technologies LLC Dubai") {
        frm.set_value(
            "naming_series",
            is_return ? "CN-D-" : "INV-D-"
        );
    }

    else if (company === "Doodle Technologies LLC") {
        frm.set_value(
            "naming_series",
            is_return ? "CN-A-" : "INV-A-"
        );
    }
}


