frappe.ui.form.on('Quotation', {

    setup: function(frm) {
        // Filter Sales Taxes and Charges Template
        frm.set_query('taxes_and_charges', function() {
            return {
                filters: {
                    company: frm.doc.company
                }
            };
        });
    },

    division: function(frm) {

        // If division is removed, clear Taxes and Charges Template
        if (!frm.doc.division) {
            frm.set_value('taxes_and_charges', '');
            return;
        }

        // Get Sales Taxes and Charges Template from Cost Center
        frappe.db.get_value(
            'Cost Center',
            frm.doc.division,
            'custom_sales_taxes_and_charges'
        ).then(r => {

            const template = r.message?.custom_sales_taxes_and_charges;

            if (template) {
                frm.set_value('taxes_and_charges', template);
            } else {
                frm.set_value('taxes_and_charges', '');

                frappe.show_alert({
                    message: __('No Sales Taxes and Charges Template is configured for this Division'),
                    indicator: 'orange'
                });
            }
        });
    }
});

